        y: r.hcaRatePct,
        z: Math.max(40, (r.gerdSharePct ?? 4) * 6),
      })),
    [],
  );

  const perimeterLabel =
    SCOREBOARD.find((s) => s.id === perimeter)?.label ?? perimeter;

  return (
