                  <YAxis tick={{ fontSize: 11 }} unit="B" />
                  <Tooltip
                    formatter={(v, name) => [
                      fmtBn(Number(v)),
                      String(name),
                    ]}
                    contentStyle={{ fontSize: 12 }}
                  />
                  <Bar
                    dataKey="chinaLeadBn"
                    name="China lead"
                    fill={ROSE}
                    radius={[4, 4, 0, 0]}
                  />
                  <Bar
                    dataKey="usLeadBn"
                    name="US lead"
                    fill={SKY}
                    radius={[4, 4, 0, 0]}
                  />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="CET field China share"
            subtitle="International priority patent families ??? AI is the volume extreme."
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={CET_FIELDS}
                  layout="vertical"
                  margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis type="number" domain={[0, 100]} tick={{ fontSize: 11 }} unit="%" />
                  <YAxis
                    type="category"
                    dataKey="short"
                    width={48}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip
                    formatter={(v) => [fmtPct(Number(v), 0), "China share"]}
                    contentStyle={{ fontSize: 12 }}
                  />
                  <Bar dataKey="chinaSharePct" radius={[0, 4, 4, 0]}>
                    {CET_FIELDS.map((r) => (
                      <Cell key={r.id} fill={r.color} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "ladder" && (
